WITH base AS (SELECT *, ROUND(amount * 0.9, 2) AS amount_scaled FROM payments WHERE order_id IS NOT NULL), payments_stats AS (SELECT method, CASE WHEN amount_scaled >= 73 THEN 'high' WHEN amount_scaled >= 32 THEN 'mid' ELSE 'low' END AS amount_scaled_bucket, COUNT(CASE WHEN method = 'paypal' THEN 1 END) AS paypal_count, COUNT(amount_scaled) AS amount_scaled_count FROM base GROUP BY method, CASE WHEN amount_scaled >= 73 THEN 'high' WHEN amount_scaled >= 32 THEN 'mid' ELSE 'low' END) SELECT method, amount_scaled_bucket, paypal_count, amount_scaled_count FROM payments_stats WHERE amount_scaled_count < 8
